// spec: specs/admin-subscriptions.md (раздел 1.2)
// seed: tests/seed.admin.spec.ts
// Расхождения плана с живой страницей (19.11.2026):
//  - во вкладке «תשלום נכשל» (URL /subscriptions?tab=failed) попадают и бесплатные аккаунты (מסלול «חינם», «ללא תפוגה»), у вкладки нет счётчика;
//  - колонка «תשלום» у строк вкладки показывает «שולם» или «—», а не «נכשל» (признак — наличие неудачной покупки у пользователя);
//  - ссылка в боковой карточке зависит от пола: «לכרטיס המשתמש/ת» или «לכרטיס המשתמשת» — проверяем по префиксу.
// Только просмотр: «הענקת …», «⋯», «כלי בדיקה» не нажимаются.
import { test, expect } from '@playwright/test';
import path from 'path';

const ADMIN_URL = 'https://magnet-admin.vercel.app';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin-r11.json') });

test.describe('Админка: «מנויים ורכישות» (#01f23b)', () => {
  test('Вкладка «תשלום נכשל» @desktop @prod-safe', async ({ page }) => {
    await page.goto(`${ADMIN_URL}/users`);

    // 1. «מנויים ורכישות» → вкладка «תשלום נכשל»
    await page.getByRole('navigation', { name: 'ניווט ראשי' }).getByRole('link', { name: 'מנויים ורכישות' }).click();
    await expect(page).toHaveURL(/\/subscriptions$/);
    const region = page.getByRole('region', { name: 'מנויים' });
    const failedTab = region.getByRole('tab', { name: 'תשלום נכשל' });
    await failedTab.click();
    await expect(page).toHaveURL(/\/subscriptions\?tab=failed/);
    await expect(failedTab).toHaveAttribute('aria-selected', 'true');

    // 2. Сравнить «מוצגים N מתוך N» с числом строк; нажать на имя пользователя в первой строке
    const shown = region.getByText(/^מוצגים \d+(–\d+)? מתוך \d+$/).first();
    await expect(shown).toBeVisible();
    const total = Number((await shown.innerText()).match(/מתוך (\d+)/)![1]);
    expect(total, 'нет неудачных платежей (ОКРУЖЕНИЕ)').toBeGreaterThanOrEqual(1);

    const userLinks = region.getByRole('link', { name: /^מנוי ורכישות של / });
    await expect(userLinks).toHaveCount(total);
    await expect(region.getByRole('row')).toHaveCount(total + 1);

    const firstLink = userLinks.first();
    const linkName = (await firstLink.getAttribute('aria-label')) ?? (await firstLink.innerText());
    const userName = linkName.replace(/^מנוי ורכישות של /, '').split('\n')[0].trim();
    await firstLink.click();

    // Карточка пользователя: заголовок с именем и «מנוי ורכישות», ссылка «לכרטיס המשתמש/ת»
    await expect(page).toHaveURL(/\/subscriptions\/[0-9a-f-]{36}$/);
    await expect(page.getByRole('heading', { level: 1, name: userName })).toBeVisible();
    await expect(page.getByText(/^מנוי ורכישות · U-[0-9A-F]{6}$/)).toBeVisible();
    await expect(page.getByRole('link', { name: /^לכרטיס המשתמש/ })).toBeVisible();
  });
});
